import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    max_count = 0
    i = 0
    while i < len(s):
        if s[i].islower():
            current_set = set()
            j = i
            while j < len(s) and s[j].islower():
                current_set.add(s[j])
                j += 1
            max_count = max(max_count, len(current_set))
            i = j
        else:
            i += 1

    print(max_count)

if __name__ == "__main__":
    solve()

